 async function prepareCampaignTest(){if(!release.internalTest||dirty||pending||!testHistoryReady||testCapability?.internalTest!==true||currentTestBlocked())return;await withCampaignTest(async c=>{const p=await call('campaigns',{acao:'campanha_teste_previa',brand:scope.brand,id:c.id,expected_version:c.version,recipient:selectedTestRecipient()},'POST');sameTestContext(c);if(p.contract!=='crm-campaign-internal-test-v1'||p.eligible!==true||p.brand!==scope.brand||p.campaign_id!==c.id||p.campaign_version!==c.version||p.recipient!==selectedTestRecipient()||!p.subject?.startsWith('[TESTE] ')){notice('campaign-test-status','A origem não liberou este teste. Confira o cadastro interno e a versão salva.','warning');return;}testPreview=p;notice('campaign-test-status','Confira antes de enviar: '+p.subject+' · remetente '+p.from_email+' · respostas '+p.reply_to+' · layout '+p.template_name+'. Destinatário: '+p.recipient+'.');});}
