 function pendingNotice(){const host=el('crm-pending');host.replaceChildren();host.className=pending?'alert alert-warning':'d-none';if(!pending)return;host.append(document.createTextNode('Uma tentativa aguarda conferência. Ela será consultada pelo mesmo identificador. '));const b=document.createElement('button'),view=pending.route==='campaigns'?'campaigns':'audiences';b.className='btn btn-sm btn-outline-secondary';b.textContent=s().view===view?'Consultar tentativa':'Abrir '+(view==='campaigns'?'Campanhas':'Públicos');b.addEventListener('click',()=>s().view===view?reconcile():reload(view));host.append(b);}
