  if(p.route==='campaigns'){const current=await call('campaigns',{acao:'campanha_obter',brand:scope.brand,id:result.campaign.id});if(current.campaign?.definition?.brand!==scope.brand)throw Error('SCOPE');campaign=current.campaign;if(p.frozenListId&&JSON.stringify(campaign.definition.list_ids)!==JSON.stringify([p.frozenListId]))throw Error('FROZEN_CREATE_LIST_CHANGED');const pos=records.findIndex(c=>c.id===campaign.id);if(pos<0)records.unshift(campaign);else records[pos]=campaign;campaignSelected(campaign.id);renderDraftList();nativeReview=p.action==='campanha_nativa_validar'?result.validation:null;forget();dirty=false;pendingNotice();await syncServerTestHistory();renderCampaign();if(p.kind==='create'&&p.frozenListId){remember({...p,phase:'created',campaignId:campaign.id});pending=null;pendingNotice();}notice('campaign-edit-status',p.kind==='native'?(campaign.status==='scheduled'&&campaign.send_at?'Agendada para '+when(campaign.send_at)+'.':campaign.status==='draft'&&!campaign.send_at?'Rascunho · sem data de envio.':campaign.status==='draft'?'Rascunho · horário '+when(campaign.send_at)+'.':'Campanha atualizada. Reabra para conferir o estado atual.'):['campanha_validar','campanha_nativa_validar'].includes(p.action)?(result.validation?.ok?'Campanha validada. '+number(result.validation.audience.eligible_count)+' destinatários elegíveis · '+when(result.validation.validatedAt):'Tentativa confirmada. A conferência de destinatários venceu; valide novamente.'):(useNativeCreator()?'Rascunho salvo.':'Rascunho salvo na origem e reaberto.'),'success');}
